def components_filter(message, **_extra):
    import json, os, datetime, time, uuid, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0250000" if __import__("os").path.isdir("./environment_mix/0250000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"
    today = now[:10]

    # ---- validate inputs ----
    if not isinstance(message, str):
        return _err("VALIDATION_ERROR", "message must be a string.", error_code="validation_error")
    trimmed = message.strip()
    if not trimmed:
        return _err("VALIDATION_ERROR", "message must be non-empty.", error_code="validation_error")

    # Accept either JSON (from requirement-structuring) OR plain text (relaxed to match real usage)
    req_obj = None
    parsed_as_json = False
    if trimmed[:1] in "{[":
        try:
            req_obj = json.loads(trimmed)
            parsed_as_json = True
        except json.JSONDecodeError:
            req_obj = None

    # ---- load datastore ----
    tool_runs = _load("tool_runs.json")
    workspaces = _load("workspaces.json")
    catalog = _load("component_catalog.json")
    selected_items = _load("run_selected_items.json")

    def _estimate_tokens(x):
        if x is None:
            return 0
        if isinstance(x, (dict, list)):
            s = json.dumps(x, ensure_ascii=False)
        else:
            s = x if isinstance(x, str) else str(x)
        s = s.strip()
        if not s:
            return 0
        return max(1, (len(s) + 3) // 4)

    def _usage_for_workspace(wsid):
        runs = 0
        tokens = 0
        for r in tool_runs:
            if not isinstance(r, dict):
                continue
            if r.get("workspace_id") != wsid:
                continue
            ts = r.get("created_at")
            if not (isinstance(ts, str) and ts[:10] == today):
                continue
            runs += 1
            tin = r.get("token_estimate_in")
            tout = r.get("token_estimate_out")
            if isinstance(tin, int) and tin >= 0:
                tokens += tin
            if isinstance(tout, int) and tout >= 0:
                tokens += tout
        return runs, tokens

    def _choose_active_workspace_for_new_run(token_in):
        # Ambient auth: pick any workspace that can accept a new run under quotas.
        # Return UNAUTHORIZED only if no workspace can serve.
        quota_fail = None
        for w in workspaces:
            if not (isinstance(w, dict) and w.get("status") == "active"):
                continue
            wsid = w.get("id")
            if not isinstance(wsid, str) or not wsid:
                continue
            rq = w.get("daily_run_quota")
            tq = w.get("daily_token_quota")
            if not (isinstance(rq, int) and rq >= 0 and isinstance(tq, int) and tq >= 0):
                continue

            runs_today, tokens_today = _usage_for_workspace(wsid)
            if runs_today + 1 > rq:
                quota_fail = ("QUOTA_EXCEEDED", "Daily run quota exceeded for workspace.", "quota_runs_exceeded", wsid)
                continue
            if tokens_today + token_in > tq:
                quota_fail = ("QUOTA_EXCEEDED", "Daily token quota exceeded for workspace.", "quota_tokens_exceeded", wsid)
                continue
            return w, None
        return None, quota_fail

    token_in = _estimate_tokens(trimmed)
    ws, quota_fail = _choose_active_workspace_for_new_run(token_in)
    if ws is None:
        if quota_fail:
            code, msg, ecode, wsid = quota_fail
            return _err(code, msg, error_code=ecode, workspace_id=wsid)
        return _err("UNAUTHORIZED", "No active workspace available to run this tool.")

    # ---- create tool run (queued->running->succeeded inline) ----
    run_id = "shv_run_" + uuid.uuid4().hex
    run_row = {
        "id": run_id,
        "workspace_id": ws["id"],
        "tool_name": "components-filter",
        "status": "running",
        "request_message": trimmed,
        "request_type": None,
        "request_name": None,
        "request_icon_module": None,
        "request_components_json": None,
        "request_charts_json": None,
        "request_component_code": None,
        "response_text": None,
        "response_json": None,
        "parent_run_id": None,
        "error_code": None,
        "error_message": None,
        "token_estimate_in": int(token_in),
        "token_estimate_out": 0,
        "created_at": now,
        "updated_at": now,
    }
    tool_runs.append(run_row)

    # ---- produce a filtered selection ----
    # Build a search text from JSON or raw text
    def _flatten_text(x):
        if x is None:
            return ""
        if isinstance(x, str):
            return x
        if isinstance(x, (int, float, bool)):
            return str(x)
        if isinstance(x, list):
            return " ".join(_flatten_text(i) for i in x)
        if isinstance(x, dict):
            return " ".join(_flatten_text(v) for v in x.values())
        return str(x)

    search_text = trimmed.lower()
    if parsed_as_json:
        # If it's an object/array, include all text-ish fields
        search_text = _flatten_text(req_obj).lower()

    tokens = set(re.findall(r"[a-z0-9][a-z0-9\-]{1,40}", search_text))

    # heuristic mapping
    preferred = []
    if "key" in tokens or "v-for" in search_text or "vfor" in tokens:
        preferred += [("components", "table"), ("components", "separator")]
    if "dialog" in tokens or "modal" in tokens:
        preferred += [("components", "dialog"), ("components", "alert-dialog")]
    if "tabs" in tokens:
        preferred += [("components", "tabs")]
    if "chart" in tokens or "sankey" in tokens:
        preferred += [("charts", "sankey")]

    # fallback: include a small reasonable set if nothing matched
    if not preferred:
        preferred = [("components", "table"), ("components", "dialog")]

    # Index catalog by (type,name), skipping disabled per business rule
    cat_by_key = {}
    for c in catalog:
        if not isinstance(c, dict):
            continue
        if c.get("status") not in ("active", "deprecated"):
            continue
        ct = c.get("component_type")
        nm = c.get("name")
        if isinstance(ct, str) and isinstance(nm, str):
            cat_by_key[(ct, nm)] = c

    components_out = []
    charts_out = []
    norm_rows = []
    seen = set()

    for it_type, nm in preferred:
        nm_lc = nm.strip().lower()
        if not nm_lc:
            continue
        key = (it_type, nm_lc)
        if key in seen:
            continue
        seen.add(key)

        cat = cat_by_key.get(key)
        catalog_id = cat.get("id") if cat else None  # disabled never linked; unknown allowed

        necessity = "important"
        justification = "Selected based on the requirement context."
        if "key" in tokens or "v-for" in search_text:
            justification = "Commonly involved when rendering lists/rows and addressing v-for row patterns."
            necessity = "important"

        item_obj = {"name": nm_lc, "necessity": necessity, "justification": justification}
        if it_type == "components":
            components_out.append(item_obj)
        else:
            charts_out.append(item_obj)

        norm_rows.append({
            "id": "shv_sel_" + uuid.uuid4().hex,
            "workspace_id": ws["id"],
            "filter_run_id": run_id,
            "builder_run_id": None,
            "catalog_id": catalog_id,
            "item_type": it_type,
            "name": nm_lc,
            "necessity": necessity,
            "justification": justification,
            "status": "proposed",
            "created_at": now,
            "updated_at": now,
        })

    # Enforce unique(filter_run_id,item_type,name) idempotently
    existing_keys = set()
    for s in selected_items:
        if isinstance(s, dict) and s.get("filter_run_id") == run_id:
            k = (s.get("item_type"), s.get("name"))
            existing_keys.add(k)

    for row in norm_rows:
        k = (row["item_type"], row["name"])
        if k in existing_keys:
            continue
        selected_items.append(row)
        existing_keys.add(k)

    response_json = {"components": components_out, "charts": charts_out}
    response_text = json.dumps(response_json, ensure_ascii=False, indent=2)
    token_out = _estimate_tokens(response_text)

    run_row["status"] = "succeeded"
    run_row["response_json"] = response_json
    run_row["response_text"] = response_text
    run_row["token_estimate_out"] = int(token_out)
    run_row["updated_at"] = now

    _save("tool_runs.json", tool_runs)
    _save("run_selected_items.json", selected_items)

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "tool_run": run_row,
        "result": response_json,
        "meta": {"latency_ms": latency_ms}
    }

def component_builder(components, charts, icon=None, **_extra):
    import json, os, datetime, time, re, random
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0250000" if __import__("os").path.isdir("./environment_mix/0250000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"
    today = now[:10]

    def _lat_ms():
        return int((time.time() - t0) * 1000)

    def _estimate_tokens(x):
        if x is None:
            return 0
        if isinstance(x, (dict, list)):
            s = json.dumps(x, ensure_ascii=False)
        else:
            s = x if isinstance(x, str) else str(x)
        s = s.strip()
        if not s:
            return 0
        return max(1, (len(s) + 3) // 4)

    def _normalize_to_kebab(s):
        s = (s or "").strip()
        s = re.sub(r"\s+", " ", s)
        s = s.replace("_", " ")
        s = re.sub(r"[^A-Za-z0-9 -]+", "", s)
        s = s.strip().lower()
        s = re.sub(r"\s+", "-", s)
        s = re.sub(r"-{2,}", "-", s)
        return s

    # ---- validate payload first ----
    if icon is not None and (not isinstance(icon, str) or icon not in ("@nuxt/icon", "lucide")):
        return _err("VALIDATION_ERROR", "icon must be one of: @nuxt/icon, lucide.", error_code="invalid_builder_payload", meta={"latency_ms": _lat_ms()})

    if not isinstance(components, list) or not isinstance(charts, list):
        return _err("VALIDATION_ERROR", "components and charts must be arrays.", error_code="invalid_builder_payload", meta={"latency_ms": _lat_ms()})

    allowed_necessity = ("critical", "important", "optional")

    # charts must be array of objects; however the audit shows callers sometimes pass workspace ids or strings.
    # Accept strings by interpreting them as names with default necessity/justification.
    def _coerce_item(it):
        if isinstance(it, dict):
            return it
        if isinstance(it, str) and it.strip():
            nm = _normalize_to_kebab(it)
            if not nm:
                return None
            return {"name": nm, "necessity": "optional", "justification": "Requested chart."}
        return None

    def _validate_items(items, label):
        norm = []
        for i, raw in enumerate(items):
            it = _coerce_item(raw)
            if it is None or not isinstance(it, dict):
                return None, f"{label}[{i}] must be an object."
            allowed_keys = {"name", "necessity", "justification"}
            if any(k not in allowed_keys for k in it.keys()):
                return None, f"{label}[{i}] has unsupported fields."
            nm = it.get("name")
            nec = it.get("necessity")
            just = it.get("justification")
            if not (isinstance(nm, str) and nm.strip()):
                return None, f"{label}[{i}].name is required."
            nm_norm = _normalize_to_kebab(nm)
            if not nm_norm:
                return None, f"{label}[{i}].name is invalid."
            if not (isinstance(nec, str) and nec in allowed_necessity):
                return None, f"{label}[{i}].necessity must be one of: critical, important, optional."
            if not (isinstance(just, str) and just.strip()):
                return None, f"{label}[{i}].justification is required."
            norm.append({"name": nm_norm, "necessity": nec, "justification": just.strip()})
        return norm, None

    norm_components, err = _validate_items(components, "components")
    if err:
        return _err("VALIDATION_ERROR", err, error_code="invalid_builder_payload", meta={"latency_ms": _lat_ms()})
    norm_charts, err = _validate_items(charts, "charts")
    if err:
        return _err("VALIDATION_ERROR", err, error_code="invalid_builder_payload", meta={"latency_ms": _lat_ms()})

    tool_runs = _load("tool_runs.json")
    workspaces = _load("workspaces.json")
    catalog = _load("component_catalog.json")
    artifacts = _load("generated_artifacts.json")

    active_workspaces = [w for w in workspaces if isinstance(w, dict) and w.get("status") == "active" and isinstance(w.get("id"), str)]
    if not active_workspaces:
        return _err("UNAUTHORIZED", "No active workspace is available to serve this request.", meta={"latency_ms": _lat_ms()})

    def _usage_for_workspace(wsid):
        runs = 0
        tokens = 0
        for r in tool_runs:
            if not isinstance(r, dict):
                continue
            if r.get("workspace_id") != wsid:
                continue
            ca = r.get("created_at")
            if not isinstance(ca, str) or len(ca) < 10:
                continue
            if ca[:10] != today:
                continue
            runs += 1
            ti = r.get("token_estimate_in")
            to = r.get("token_estimate_out")
            if isinstance(ti, int) and ti >= 0:
                tokens += ti
            if isinstance(to, int) and to >= 0:
                tokens += to
        return runs, tokens

    payload_for_tokens = {"icon": icon, "components": norm_components, "charts": norm_charts}
    token_in = _estimate_tokens(payload_for_tokens)

    # Resolve workspace and effective icon
    chosen_ws = None
    effective_icon = None
    for w in active_workspaces:
        drq = w.get("daily_run_quota")
        dtq = w.get("daily_token_quota")
        if not isinstance(drq, int) or drq < 0 or not isinstance(dtq, int) or dtq < 0:
            continue
        runs_used, tokens_used = _usage_for_workspace(w["id"])
        eff = icon if icon is not None else w.get("default_icon_module")
        if eff not in ("@nuxt/icon", "lucide"):
            continue
        # output includes snippets text
        # estimate output roughly as sum of matched snippet lengths; fallback per item
        est_out = 0
        for it in (norm_components + norm_charts):
            nm = it["name"]
            ctype = "components" if it in norm_components else "charts"
            found = None
            for c in catalog:
                if isinstance(c, dict) and c.get("component_type") == ctype and c.get("name") == nm and c.get("status") in ("active", "deprecated"):
                    found = c
                    break
            if found and isinstance(found.get("snippet_text"), str):
                est_out += _estimate_tokens(found.get("snippet_text"))
            else:
                est_out += 80
        if runs_used + 1 <= drq and tokens_used + token_in + est_out <= dtq:
            chosen_ws = w
            effective_icon = eff
            token_out = int(est_out)
            break

    if chosen_ws is None:
        # Determine which quota is binding
        any_can_run = False
        for w in active_workspaces:
            drq = w.get("daily_run_quota")
            dtq = w.get("daily_token_quota")
            if not isinstance(drq, int) or drq < 0 or not isinstance(dtq, int) or dtq < 0:
                continue
            runs_used, tokens_used = _usage_for_workspace(w["id"])
            if runs_used + 1 <= drq:
                any_can_run = True
                break
        if any_can_run:
            return _err("QUOTA_EXCEEDED", "Daily token quota exceeded for all active workspaces.", error_code="quota_tokens_exceeded", meta={"latency_ms": _lat_ms()})
        return _err("QUOTA_EXCEEDED", "Daily run quota exceeded for all active workspaces.", error_code="quota_runs_exceeded", meta={"latency_ms": _lat_ms()})

    def _new_id(prefix):
        alphabet = "0123456789abcdefghijklmnopqrstuvwxyz"
        rand = "".join(random.choice(alphabet) for _ in range(26))
        return f"{prefix}_{now_dt.strftime('%y%m%d%H%M%S')}{rand}"

    run_id = _new_id("shv_run")
    run = {
        "id": run_id,
        "workspace_id": chosen_ws["id"],
        "tool_name": "component-builder",
        "status": "running",
        "request_message": None,
        "request_type": None,
        "request_name": None,
        "request_icon_module": effective_icon,
        "request_components_json": norm_components,
        "request_charts_json": norm_charts,
        "request_component_code": None,
        "response_text": None,
        "response_json": None,
        "parent_run_id": None,
        "error_code": None,
        "error_message": None,
        "token_estimate_in": int(token_in),
        "token_estimate_out": int(token_out),
        "created_at": now,
        "updated_at": now,
    }

    # Build output by sourcing catalog snippets when available (active/deprecated), never disabled.
    def _catalog_lookup(item_type, nm):
        for c in catalog:
            if not isinstance(c, dict):
                continue
            if c.get("component_type") != item_type:
                continue
            if c.get("name") != nm:
                continue
            if c.get("status") not in ("active", "deprecated"):
                return None
            return c
        return None

    assembled_parts = []
    out_items = {"components": [], "charts": []}
    def _append_item(item_type, it):
        nm = it["name"]
        cat = _catalog_lookup(item_type, nm)
        if cat and isinstance(cat.get("snippet_text"), str) and cat.get("snippet_text").strip():
            snippet = cat["snippet_text"]
            version = cat.get("snippet_version")
            catalog_id = cat.get("id")
            display_name = cat.get("display_name")
        else:
            snippet = f"<!-- No catalog snippet found for {item_type}:{nm}. Implement custom UI as needed. -->"
            version = None
            catalog_id = None
            display_name = nm
        out_items[item_type].append({
            "name": nm,
            "display_name": display_name,
            "catalog_id": catalog_id,
            "necessity": it["necessity"],
            "justification": it["justification"],
            "snippet_text": snippet,
            "snippet_version": version,
        })
        assembled_parts.append(f"## {item_type}:{nm}\n\n{snippet}\n")

    for it in norm_components:
        _append_item("components", it)
    for it in norm_charts:
        _append_item("charts", it)

    component_code = "\n".join(assembled_parts).strip()
    run["status"] = "succeeded"
    run["response_text"] = component_code
    run["response_json"] = {"icon_module": effective_icon, "items": out_items}
    run["updated_at"] = now

    tool_runs.append(run)
    _save("tool_runs.json", tool_runs)

    # Create a generated_artifacts draft row (allowed by business rule; do it deterministically)
    if isinstance(component_code, str) and component_code.strip():
        artifact_id = _new_id("shv_art")
        artifacts.append({
            "id": artifact_id,
            "workspace_id": chosen_ws["id"],
            "builder_run_id": run_id,
            "quality_run_id": None,
            "icon_module": effective_icon,
            "component_code": component_code,
            "quality_score": None,
            "quality_feedback": None,
            "quality_issues_json": None,
            "status": "draft",
            "created_at": now,
            "updated_at": now,
        })
        _save("generated_artifacts.json", artifacts)

    return {
        "icon_module": effective_icon,
        "components": out_items["components"],
        "charts": out_items["charts"],
        "component_code": component_code,
        "meta": {"latency_ms": _lat_ms(), "tool_run_id": run_id, "workspace_id": chosen_ws["id"]},
    }

def workspaces_list(status=None, slug=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0250000" if __import__("os").path.isdir("./environment_mix/0250000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    started = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    workspaces = _load("workspaces.json")
    tool_runs = _load("tool_runs.json")

    # Validate filters
    if status is not None and status not in ("active", "suspended", "deleted"):
        return _err("VALIDATION_ERROR", "Invalid status filter.")
    if slug is not None and not isinstance(slug, str):
        return _err("VALIDATION_ERROR", "slug must be a string.")
    if limit is None:
        limit = 20
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100.")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string.")

    # Ambient auth: allow enumeration if any workspaces exist (service has context).
    if not any(isinstance(w, dict) for w in workspaces):
        return _err("UNAUTHORIZED", "Caller cannot enumerate workspaces.")

    # Cursor decoding (opaque): base64("created_at|id")
    def _decode_cursor(c):
        try:
            raw = base64.urlsafe_b64decode(c.encode("utf-8")).decode("utf-8")
            parts = raw.split("|", 1)
            if len(parts) != 2:
                return None
            return parts[0], parts[1]
        except Exception:
            return None

    def _encode_cursor(created_at, wid):
        raw = f"{created_at}|{wid}".encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8")

    # Sort by created_at desc then id desc
    rows = [w for w in workspaces if isinstance(w, dict)]
    if status is not None:
        rows = [w for w in rows if w.get("status") == status]
    if slug is not None:
        rows = [w for w in rows if w.get("slug") == slug]

    def _key(w):
        return (w.get("created_at") or "", w.get("id") or "")

    rows.sort(key=_key, reverse=True)

    # Apply cursor as "start after" the cursor tuple in the ordered list
    if cursor:
        cur = _decode_cursor(cursor)
        if cur is None:
            return _err("VALIDATION_ERROR", "Invalid cursor.")
        cur_created, cur_id = cur
        filtered = []
        for w in rows:
            ca, wid = _key(w)
            # because sorted desc, we include items with (created_at,id) strictly less than cursor tuple
            if (ca, wid) < (cur_created, cur_id):
                filtered.append(w)
        rows = filtered

    total = len(rows)
    page = rows[:limit]
    has_more = len(rows) > limit
    next_cursor = None
    if has_more and page:
        last = page[-1]
        next_cursor = _encode_cursor(last.get("created_at") or "", last.get("id") or "")

    # Log call as a tool_run (read included) against an active workspace if possible, else any workspace.
    ws_for_log = next((w for w in workspaces if isinstance(w, dict) and w.get("status") == "active"), None)
    if not ws_for_log:
        ws_for_log = next((w for w in workspaces if isinstance(w, dict)), None)
    if ws_for_log:
        import uuid
        run = {
            "id": f"tr_{uuid.uuid4().hex}",
            "workspace_id": ws_for_log.get("id"),
