    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0250000" if __import__("os").path.isdir("./environment_mix/0250000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _lat_ms():
        return int((time.time() - t0) * 1000)

    # validate
    if not isinstance(slug, str):
        return _err("VALIDATION_ERROR", "slug must be a string.", error_code="validation_error", meta={"latency_ms": _lat_ms()})
    slug = slug.strip()
    if not (2 <= len(slug) <= 64):
        return _err("VALIDATION_ERROR", "slug length must be 2..64.", error_code="validation_error", meta={"latency_ms": _lat_ms()})
    if not re.fullmatch(r"^[a-z0-9]+(?:-[a-z0-9]+)*$", slug):
        return _err("VALIDATION_ERROR", "slug must match ^[a-z0-9]+(?:-[a-z0-9]+)*$.", error_code="validation_error", meta={"latency_ms": _lat_ms()})

    if not isinstance(name, str):
        return _err("VALIDATION_ERROR", "name must be a string.", error_code="validation_error", meta={"latency_ms": _lat_ms()})
    name = " ".join(name.strip().split())
    if not (1 <= len(name) <= 120):
        return _err("VALIDATION_ERROR", "name length must be 1..120.", error_code="validation_error", meta={"latency_ms": _lat_ms()})

    if default_icon_module is None:
        default_icon_module = "lucide"
    if not isinstance(default_icon_module, str) or default_icon_module not in ("@nuxt/icon", "lucide"):
        return _err("VALIDATION_ERROR", "default_icon_module must be one of: @nuxt/icon, lucide.", error_code="validation_error", meta={"latency_ms": _lat_ms()})

    if daily_run_quota is None:
        daily_run_quota = 0
    if daily_token_quota is None:
        daily_token_quota = 0
    if not isinstance(daily_run_quota, int) or daily_run_quota < 0:
        return _err("VALIDATION_ERROR", "daily_run_quota must be an integer >= 0.", error_code="validation_error", meta={"latency_ms": _lat_ms()})
    if not isinstance(daily_token_quota, int) or daily_token_quota < 0:
        return _err("VALIDATION_ERROR", "daily_token_quota must be an integer >= 0.", error_code="validation_error", meta={"latency_ms": _lat_ms()})

    workspaces = _load("workspaces.json")

    # Idempotency: if a workspace already exists with this slug (any status), return it.
    for w in workspaces:
        if isinstance(w, dict) and w.get("slug") == slug:
            # Treat as idempotent create: return existing row rather than CONFLICT.
            return {"workspace": w, "meta": {"latency_ms": _lat_ms(), "idempotent": True}}

    def _new_id(prefix):
        return prefix + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S") + "%08d" % random.randint(0, 99999999)

    ws = {
        "id": _new_id("shv_ws_"),
        "slug": slug,
        "name": name,
        "status": "active",
        "default_icon_module": default_icon_module,
        "daily_run_quota": int(daily_run_quota),
        "daily_token_quota": int(daily_token_quota),
        "created_at": now,
        "updated_at": now,
    }
    workspaces.append(ws)
    _save("workspaces.json", workspaces)

    return {"workspace": ws, "meta": {"latency_ms": _lat_ms(), "idempotent": False}}

def workspaces_update(id, name=None, default_icon_module=None, daily_run_quota=None, daily_token_quota=None, status=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0250000" if __import__("os").path.isdir("./environment_mix/0250000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    started = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    if not isinstance(id, str) or id.strip() == "":
        return _err("VALIDATION_ERROR", "id must be a non-empty string.")

    if name is not None:
        if not isinstance(name, str) or not (1 <= len(name) <= 120):
            return _err("VALIDATION_ERROR", "name must be a string of length 1..120.")
