    if daily_token_quota is not None and (not isinstance(daily_token_quota, int) or daily_token_quota < 0):
        return _err("VALIDATION_ERROR", "daily_token_quota must be an integer >= 0.")
    if status is not None and status not in ("active", "suspended", "deleted"):
        return _err("VALIDATION_ERROR", "status must be one of active, suspended, deleted.")

    workspaces = _load("workspaces.json")
    tool_runs = _load("tool_runs.json")

    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == id), None)
    if not ws:
        return _err("NOT_FOUND", "Workspace not found.")

    if ws.get("status") == "deleted":
        return _err("CONFLICT", "Workspace is deleted and cannot be updated.")

    # Enforce unique slug not touched (no slug param)
    # Enforce lifecycle transitions
    transitions = {
        "active": {"suspended", "deleted"},
        "suspended": {"active", "deleted"},
        "deleted": set()
    }
    if status is not None and status != ws.get("status"):
        cur = ws.get("status")
        if status not in transitions.get(cur, set()):
            return _err("CONFLICT", f"Illegal status transition {cur} -> {status}.")

    # Apply updates
    changed = False
    if name is not None and name != ws.get("name"):
        ws["name"] = name
        changed = True
    if default_icon_module is not None and default_icon_module != ws.get("default_icon_module"):
        ws["default_icon_module"] = default_icon_module
        changed = True
    if daily_run_quota is not None and daily_run_quota != ws.get("daily_run_quota"):
        ws["daily_run_quota"] = daily_run_quota
        changed = True
    if daily_token_quota is not None and daily_token_quota != ws.get("daily_token_quota"):
        ws["daily_token_quota"] = daily_token_quota
        changed = True
    if status is not None and status != ws.get("status"):
        ws["status"] = status
        changed = True

    if not changed:
        # No success without effect: treat as NOT_FOUND-equivalent? For update, more accurate is conflict/validation.
        return _err("CONFLICT", "No changes applied.")

    ws["updated_at"] = now
    _save("workspaces.json", workspaces)

    # Log call
    try:
        run = {
            "id": f"tr_{uuid.uuid4().hex}",
            "workspace_id": ws.get("id"),
            "tool_name": "components-filter",
            "status": "succeeded",
            "request_message": None,
            "request_type": None,
            "request_name": None,
            "request_icon_module": None,
            "request_components_json": None,
            "request_charts_json": None,
            "request_component_code": None,
            "response_text": None,
            "response_json": {"endpoint": "workspaces-update", "workspace_id": ws.get("id")},
            "parent_run_id": None,
            "error_code": None,
            "error_message": None,
            "token_estimate_in": 1,
            "token_estimate_out": 1,
            "created_at": now,
            "updated_at": now
        }
        tool_runs.append(run)
        _save("tool_runs.json", tool_runs)
    except Exception:
        pass

    latency_ms = int((time.time() - started) * 1000)
    return {"data": ws, "meta": {"latency_ms": latency_ms}}

def tool_runs_list(workspace_id, tool_name=None, status=None, since=None, until=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0250000" if __import__("os").path.isdir("./environment_mix/0250000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _dt_parse(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            return datetime.datetime.fromisoformat(s2)
        except Exception:
            return None

    # Validate inputs
    if not isinstance(workspace_id, str) or not workspace_id:
        return _err("VALIDATION_ERROR", "workspace_id must be a non-empty string.")
    valid_tool_names = {"requirement-structuring", "components-filter", "component-usage-doc", "component-builder", "component-quality-check"}
    if tool_name is not None and (not isinstance(tool_name, str) or tool_name not in valid_tool_names):
        return _err("VALIDATION_ERROR", "tool_name is invalid.")
    valid_status = {"queued", "running", "succeeded", "failed", "cancelled"}
    if status is not None and (not isinstance(status, str) or status not in valid_status):
        return _err("VALIDATION_ERROR", "status is invalid.")
    if limit is None:
        limit = 20
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100.")

    since_dt = None
    until_dt = None
    if since is not None:
        since_dt = _dt_parse(since)
        if since_dt is None:
            return _err("VALIDATION_ERROR", "since must be an RFC3339 date-time string.")
    if until is not None:
        until_dt = _dt_parse(until)
        if until_dt is None:
            return _err("VALIDATION_ERROR", "until must be an RFC3339 date-time string.")
    if since_dt and until_dt and since_dt > until_dt:
        return _err("VALIDATION_ERROR", "since must be <= until.")

    workspaces = _load("workspaces.json")
    tool_runs = _load("tool_runs.json")

    # Ambient auth: if workspace exists, assume caller can access it unless no workspace exists at all.
    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if ws is None:
        return _err("NOT_FOUND", "Workspace not found.")
    # If you want to enforce access, you'd need an auth mapping collection which doesn't exist.
    # Therefore: UNAUTHORIZED only if there is no eligible context at all (not applicable here).
    # Keep behavior: allow listing even if suspended/deleted, since tool runs are persisted; vendor says refuse
    # when caller cannot access workspace, which we cannot distinguish -> treat as authorized.

    # Pagination cursor: base64 of "created_at|id" last seen
    def _decode_cursor(c):
        if c is None:
            return None
        if not isinstance(c, str) or not c:
            return "bad"
        try:
            raw = base64.urlsafe_b64decode(c.encode("utf-8") + b"===")
            s = raw.decode("utf-8")
            parts = s.split("|", 1)
            if len(parts) != 2:
                return "bad"
            dt = _dt_parse(parts[0])
            if dt is None:
                return "bad"
            return (dt, parts[1])
        except Exception:
            return "bad"

    cur = _decode_cursor(cursor)
    if cur == "bad":
        return _err("VALIDATION_ERROR", "cursor is invalid.")

    # Filter
    rows = [r for r in tool_runs if r.get("workspace_id") == workspace_id]
    if tool_name is not None:
        rows = [r for r in rows if r.get("tool_name") == tool_name]
    if status is not None:
        rows = [r for r in rows if r.get("status") == status]
    if since_dt is not None:
        rows = [r for r in rows if (_dt_parse(r.get("created_at")) is not None and _dt_parse(r.get("created_at")) >= since_dt)]
    if until_dt is not None:
        rows = [r for r in rows if (_dt_parse(r.get("created_at")) is not None and _dt_parse(r.get("created_at")) < until_dt)]

    # Sort created_at desc, tie-breaker id desc
    def _key(r):
        dt = _dt_parse(r.get("created_at"))
        if dt is None:
            dt = datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
        return (dt, str(r.get("id") or ""))
    rows.sort(key=_key, reverse=True)

    # Apply cursor (exclusive): return items created before the cursor (or same created_at with id < cursor_id)
    if cur is not None:
        cur_dt, cur_id = cur
        filtered = []
        for r in rows:
            dt = _dt_parse(r.get("created_at"))
            if dt is None:
                continue
            rid = str(r.get("id") or "")
            if dt < cur_dt:
                filtered.append(r)
            elif dt == cur_dt and rid < cur_id:
                filtered.append(r)
        rows = filtered

    total = len(rows)
    page = rows[:limit]
    has_more = total > limit

    next_cursor = None
    if has_more and page:
        last = page[-1]
        last_dt = _dt_parse(last.get("created_at"))
        if last_dt is None:
            last_dt = datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
        last_dt_s = last_dt.replace(microsecond=0).isoformat().replace("+00:00", "Z")
        payload = f"{last_dt_s}|{last.get('id')}"
        next_cursor = base64.urlsafe_b64encode(payload.encode("utf-8")).decode("utf-8").rstrip("=")

    latency_ms = int(round((time.time() - _t0) * 1000))

    # Record call dynamics: read calls also log a tool_run? Schema uses tool_runs for tool invocations only.
    # There is no separate request-log collection; do not fabricate tool_runs for listing.
    return {
        "workspace": {"id": ws.get("id"), "slug": ws.get("slug"), "name": ws.get("name"), "status": ws.get("status")},
        "data": page,
        "pagination": {
            "limit": limit,
            "total_matched": total,
            "has_more": bool(has_more),
            "next_cursor": next_cursor
        },
        "meta": {"latency_ms": latency_ms, "timestamp": _now()},
    }

def tool_runs_update(id, status=None, response_text=None, response_json=None, error_code=None, error_message=None, token_estimate_in=None, token_estimate_out=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0250000" if __import__("os").path.isdir("./environment_mix/0250000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _lat_ms():
        return int((time.time() - t0) * 1000)

    if id is None or not isinstance(id, str) or not id.strip():
        return _err("VALIDATION_ERROR", "id is required and must be a non-empty string.", meta={"latency_ms": _lat_ms()})
    id = id.strip()

    if status is not None and (not isinstance(status, str) or status not in ("queued", "running", "succeeded", "failed", "cancelled")):
        return _err("VALIDATION_ERROR", "status must be one of: queued, running, succeeded, failed, cancelled.", meta={"latency_ms": _lat_ms()})

    if response_text is not None and not isinstance(response_text, str):
        return _err("VALIDATION_ERROR", "response_text must be a string.", meta={"latency_ms": _lat_ms()})
    if response_json is not None and not isinstance(response_json, dict):
        return _err("VALIDATION_ERROR", "response_json must be an object.", meta={"latency_ms": _lat_ms()})

    if error_code is not None and not isinstance(error_code, str):
        return _err("VALIDATION_ERROR", "error_code must be a string.", meta={"latency_ms": _lat_ms()})
    if error_message is not None and not isinstance(error_message, str):
        return _err("VALIDATION_ERROR", "error_message must be a string.", meta={"latency_ms": _lat_ms()})

    if token_estimate_in is not None and (not isinstance(token_estimate_in, int) or token_estimate_in < 0):
        return _err("VALIDATION_ERROR", "token_estimate_in must be an integer >= 0.", meta={"latency_ms": _lat_ms()})
    if token_estimate_out is not None and (not isinstance(token_estimate_out, int) or token_estimate_out < 0):
        return _err("VALIDATION_ERROR", "token_estimate_out must be an integer >= 0.", meta={"latency_ms": _lat_ms()})

    tool_runs = _load("tool_runs.json")
    artifacts = _load("generated_artifacts.json")

    # Find tool run by id; be tolerant to callers passing a workspace id by mistake:
    # If no exact match, do NOT succeed; return NOT_FOUND.
    run_idx = None
    for i, r in enumerate(tool_runs):
        if isinstance(r, dict) and r.get("id") == id:
            run_idx = i
            break
    if run_idx is None:
        return _err("NOT_FOUND", "Tool run not found.", id=id, meta={"latency_ms": _lat_ms()})

    run = tool_runs[run_idx]
    tool_name = run.get("tool_name")

    # Validate field compatibility for given tool_name
    # request_* constraints are on creation, but updates must not introduce incompatible request fields either.
    if tool_name in ("requirement-structuring", "components-filter"):
        # these tools should not set request_type/request_name/request_component_code
        if run.get("request_type") is not None or run.get("request_name") is not None or run.get("request_component_code") is not None:
            return _err("VALIDATION_ERROR", "Incompatible request fields present for this tool run type.", meta={"latency_ms": _lat_ms()})
    if tool_name == "component-usage-doc":
        if run.get("request_type") not in ("components", "charts") or not isinstance(run.get("request_name"), str) or not run.get("request_name"):
            return _err("VALIDATION_ERROR", "component-usage-doc runs must have request_type and request_name.", meta={"latency_ms": _lat_ms()})
    if tool_name == "component-builder":
        if run.get("request_components_json") is None or run.get("request_charts_json") is None:
            return _err("VALIDATION_ERROR", "component-builder runs must have request_components_json and request_charts_json.", meta={"latency_ms": _lat_ms()})
    if tool_name == "component-quality-check":
        if run.get("request_component_code") is None:
            return _err("VALIDATION_ERROR", "component-quality-check runs must have request_component_code.", meta={"latency_ms": _lat_ms()})

    # Lifecycle transitions enforcement
    transitions = {
        "queued": ("running", "cancelled", "failed"),
        "running": ("succeeded", "failed", "cancelled"),
        "succeeded": (),
        "failed": (),
        "cancelled": (),
    }
    if status is not None:
        cur = run.get("status")
        if cur not in transitions:
            return _err("INVALID_TRANSITION", "Current status is invalid.", current_status=cur, meta={"latency_ms": _lat_ms()})
        if status != cur and status not in transitions[cur]:
            return _err("CONFLICT", "Illegal status transition.", current_status=cur, new_status=status, meta={"latency_ms": _lat_ms()})

    # failed must carry error_code and error_message (service rule implied by schema usage)
    if status == "failed":
        if error_code is None and not run.get("error_code"):
            return _err("VALIDATION_ERROR", "error_code is required when status=failed.", meta={"latency_ms": _lat_ms()})
        if error_message is None and not run.get("error_message"):
            return _err("VALIDATION_ERROR", "error_message is required when status=failed.", meta={"latency_ms": _lat_ms()})

    # Apply updates (no success without effect: require at least one field change)
    changed = False
    def _set(field, val):
        nonlocal changed
        if val is None:
            return
        if run.get(field) != val:
            run[field] = val
            changed = True

    _set("status", status)
    _set("response_text", response_text)
    _set("response_json", response_json)
    _set("error_code", error_code)
    _set("error_message", error_message)
    _set("token_estimate_in", token_estimate_in)
    _set("token_estimate_out", token_estimate_out)

    if not changed:
        return _err("CONFLICT", "No changes to apply.", meta={"latency_ms": _lat_ms()})

    run["updated_at"] = now

    # Business rule: on successful quality-check, update an artifact linked by quality_run_id and transition to checked
    if tool_name == "component-quality-check" and status == "succeeded":
        # Find artifact linked by quality_run_id == this run id
        art_idx = None
        for i, a in enumerate(artifacts):
            if isinstance(a, dict) and a.get("quality_run_id") == id:
                art_idx = i
                break
        if art_idx is not None:
            art = artifacts[art_idx]
            # Transition draft -> checked, checked -> checked (idempotent), approved -> checked not allowed, archived not allowed
            art_transitions = {
                "draft": ("checked", "archived"),
                "checked": ("approved", "draft", "archived"),
                "approved": ("archived",),
                "archived": (),
            }
            cur_s = art.get("status")
            if cur_s in art_transitions and "checked" in art_transitions[cur_s]:
                art["status"] = "checked"
            elif cur_s == "checked":
                pass
            else:
                return _err("INVALID_TRANSITION", "Cannot transition artifact to checked from its current status.", artifact_id=art.get("id"), current_status=cur_s, meta={"latency_ms": _lat_ms()})
            # Populate feedback fields from run response
            if isinstance(run.get("response_text"), str):
                art["quality_feedback"] = run.get("response_text")
            if isinstance(run.get("response_json"), dict):
                art["quality_issues_json"] = run.get("response_json")
            art["updated_at"] = now
            artifacts[art_idx] = art
            _save("generated_artifacts.json", artifacts)

    tool_runs[run_idx] = run
    _save("tool_runs.json", tool_runs)

    return {"tool_run": run, "meta": {"latency_ms": _lat_ms()}}

def whoami(workspace_id=None, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0250000" if __import__("os").path.isdir("./environment_mix/0250000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = datetime.datetime.utcnow()

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if s is None or not isinstance(s, str) or not s.strip():
            return None
        ss = s.strip()
        try:
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return None

    def _utc_day_key(dt):
        return dt.strftime("%Y-%m-%d")

    def _record(endpoint, workspace_id, status_code, extra=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        dt = datetime.datetime.utcnow()
        rec = {
            "id": f"req_{dt.strftime('%Y%m%d%H%M%S')}_{len(logs)+1}",
            "endpoint": endpoint,
            "workspace_id": workspace_id,
            "tool_name": None,
            "status": status_code,
            "timestamp": _now_iso(),
            "latency_ms": max(0, int((datetime.datetime.utcnow() - t0).total_seconds() * 1000)),
        }
        if isinstance(extra, dict):
            rec.update(extra)
        logs.append(rec)
        _save("request_logs.json", logs)

    if workspace_id is not None and (not isinstance(workspace_id, str) or not workspace_id.strip()):
        _record("whoami", None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "workspace_id must be a non-empty string when provided")

    workspaces = _load("workspaces.json")
    if not isinstance(workspaces, list):
        workspaces = []

    # Ambient auth resolution:
    # - If workspace_id is provided, authenticate by proving that workspace exists.
    # - If omitted, authenticate by finding any non-deleted workspace as the active context.
    ws = None
    if workspace_id is not None:
        ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
        if ws is None:
            _record("whoami", workspace_id, "UNAUTHORIZED")
            return _err("UNAUTHORIZED", "No valid credential/workspace context available for requested workspace.")
    else:
        ws = next((w for w in workspaces if isinstance(w, dict) and w.get("status") in ("active", "suspended")), None)
        if ws is None:
            _record("whoami", None, "UNAUTHORIZED")
            return _err("UNAUTHORIZED", "No valid credential/workspace context available.")

    runs = _load("tool_runs.json")
    if not isinstance(runs, list):
        runs = []

    # Quota consumption for current UTC day
    now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    day_key = _utc_day_key(now)

    run_count = 0
    token_sum = 0
    for r in runs:
        if not isinstance(r, dict):
            continue
        if r.get("workspace_id") != ws.get("id"):
            continue
        cdt = _parse_dt(r.get("created_at"))
        if cdt is None:
            continue
        if _utc_day_key(cdt) != day_key:
            continue
        run_count += 1
        tin = r.get("token_estimate_in")
        tout = r.get("token_estimate_out")
        if isinstance(tin, int) and tin >= 0:
            token_sum += tin
        if isinstance(tout, int) and tout >= 0:
            token_sum += tout

    daily_run_quota = ws.get("daily_run_quota") if isinstance(ws.get("daily_run_quota"), int) else None
    daily_token_quota = ws.get("daily_token_quota") if isinstance(ws.get("daily_token_quota"), int) else None

    _record("whoami", ws.get("id"), "OK")

    # "granted scopes" aren't modeled; return service-level defaults.
    return {
        "data": {
            "identity": {
                "type": "workspace_context",
                "workspace_id": ws.get("id"),
                "workspace_slug": ws.get("slug"),
                "workspace_status": ws.get("status"),
            },
            "scopes": [
                "tool_runs:read",
                "tool_runs:write",
                "catalog:read",
                "artifacts:read",
                "artifacts:write",
            ],
            "quota": {
                "utc_day": day_key,
                "runs": {
                    "used": run_count,
                    "limit": daily_run_quota,
                    "remaining": None if daily_run_quota is None else max(0, daily_run_quota - run_count),
                },
                "tokens": {
                    "used": token_sum,
                    "limit": daily_token_quota,
                    "remaining": None if daily_token_quota is None else max(0, daily_token_quota - token_sum),
                },
            },
            "rate_limit": {
                "modeled": False,
                "message": "Rate limiting is not configured in the local datastore schema; only daily quotas are tracked.",
            },
        }
    }
